"use strict";(globalThis.webpackChunkopen_prompt_engineering_guide=globalThis.webpackChunkopen_prompt_engineering_guide||[]).push([[4326],{5837:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"guideSidebar":[{"type":"link","href":"/open-prompting-guide/docs/intro","label":"Introduction to Prompt Engineering","docId":"intro","unlisted":false},{"type":"category","label":"Core Techniques","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/open-prompting-guide/docs/core-techniques/zero-few-shot","label":"Zero-Shot & Few-Shot Prompting","docId":"core-techniques/zero-few-shot","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/cot","label":"Chain-of-Thought Prompting","docId":"core-techniques/cot","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/meta-prompting","label":"Meta Prompting","docId":"core-techniques/meta-prompting","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/self-consistency","label":"Self-Consistency","docId":"core-techniques/self-consistency","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/gkp","label":"Generated Knowledge Prompting","docId":"core-techniques/gkp","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/prompt-chaining","label":"Prompt Chaining","docId":"core-techniques/prompt-chaining","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/tot","label":"Tree of Thoughts (ToT)","docId":"core-techniques/tot","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/rag","label":"Retrieval-Augmented Generation (RAG)","docId":"core-techniques/rag","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/art","label":"Automatic Reasoning and Tool-use (ART)","docId":"core-techniques/art","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/ape","label":"Automatic Prompt Engineer (APE)","docId":"core-techniques/ape","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/active-prompt","label":"Active-Prompt","docId":"core-techniques/active-prompt","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/dsp","label":"Directional Stimulus Prompting (DSP)","docId":"core-techniques/dsp","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/pal","label":"Program-Aided Language Models (PAL)","docId":"core-techniques/pal","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/react","label":"ReAct Prompting","docId":"core-techniques/react","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/reflexion","label":"Reflexion","docId":"core-techniques/reflexion","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/core-techniques/multimodalcot","label":"Multimodal Chain-of-Thought Prompting","docId":"core-techniques/multimodalcot","unlisted":false}],"href":"/open-prompting-guide/docs/category/core-techniques"},{"type":"category","label":"AI Agents","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/open-prompting-guide/docs/ai-agents/introduction","label":"Introduction to AI Agents","docId":"ai-agents/introduction","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/ai-agents/ai-workflows-vs-ai-agents","label":"AI Workflows vs. AI Agents","docId":"ai-agents/ai-workflows-vs-ai-agents","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/ai-agents/context-engineering","label":"Context Engineering for AI Agents","docId":"ai-agents/context-engineering","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/ai-agents/context-engineering-deep-dive","label":"Context Engineering Deep Dive: Building a Deep Research Agent","docId":"ai-agents/context-engineering-deep-dive","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/ai-agents/function-calling","label":"Function Calling in AI Agents","docId":"ai-agents/function-calling","unlisted":false},{"type":"link","href":"/open-prompting-guide/docs/ai-agents/deep-agents","label":"Deep Agents","docId":"ai-agents/deep-agents","unlisted":false}],"href":"/open-prompting-guide/docs/category/ai-agents"}]},"docs":{"ai-agents/ai-workflows-vs-ai-agents":{"id":"ai-agents/ai-workflows-vs-ai-agents","title":"AI Workflows vs. AI Agents","description":"You\'ve learned that AI agents can combine language models, tools, memory, and planning to complete complex tasks.","sidebar":"guideSidebar"},"ai-agents/context-engineering":{"id":"ai-agents/context-engineering","title":"Context Engineering for AI Agents","description":"When building AI agents, the quality of the results often depends less on the model itself and more on the context you give it.","sidebar":"guideSidebar"},"ai-agents/context-engineering-deep-dive":{"id":"ai-agents/context-engineering-deep-dive","title":"Context Engineering Deep Dive: Building a Deep Research Agent","description":"You\'ve learned how context engineering helps AI agents follow instructions, use tools, manage information, and handle unexpected situations.","sidebar":"guideSidebar"},"ai-agents/deep-agents":{"id":"ai-agents/deep-agents","title":"Deep Agents","description":"You\'ve learned how function calling allows AI agents to interact with external tools, how context engineering improves their behavior, and how multiple agents can collaborate on complex tasks.","sidebar":"guideSidebar"},"ai-agents/function-calling":{"id":"ai-agents/function-calling","title":"Function Calling in AI Agents","description":"You\'ve learned how context engineering helps AI agents use instructions, tools, and memory more effectively. You\'ve also explored how separating responsibilities can make complex agentic systems easier to manage and debug.","sidebar":"guideSidebar"},"ai-agents/introduction":{"id":"ai-agents/introduction","title":"Introduction to AI Agents","description":"Throughout this guide, you have learned how to write effective prompts, guide step-by-step reasoning, chain tasks together, and integrate external knowledge and tools.","sidebar":"guideSidebar"},"core-techniques/active-prompt":{"id":"core-techniques/active-prompt","title":"Active-Prompt","description":"You\u2019ve learned how techniques like Few-Shot CoT rely on human-annotated step-by-step examples to guide language models through complex reasoning tasks.","sidebar":"guideSidebar"},"core-techniques/ape":{"id":"core-techniques/ape","title":"Automatic Prompt Engineer (APE)","description":"You\u2019ve learned how to design prompts manually \u2014 from writing clear instructions and few-shot examples to structuring multi-step reasoning, RAG pipelines, and tool execution.","sidebar":"guideSidebar"},"core-techniques/art":{"id":"core-techniques/art","title":"Automatic Reasoning and Tool-use (ART)","description":"You\u2019ve learned how to break tasks into linear pipelines, explore branching thoughts, and ground models using external knowledge through RAG.","sidebar":"guideSidebar"},"core-techniques/cot":{"id":"core-techniques/cot","title":"Chain-of-Thought Prompting","description":"You\'ve seen how examples can shape what a model says.","sidebar":"guideSidebar"},"core-techniques/dsp":{"id":"core-techniques/dsp","title":"Directional Stimulus Prompting (DSP)","description":"You\u2019ve learned how to optimize prompts automatically using frameworks like APE, select high-value annotations with Active-Prompt, and ground model responses using external tools or RAG.","sidebar":"guideSidebar"},"core-techniques/gkp":{"id":"core-techniques/gkp","title":"Generated Knowledge Prompting","description":"You\u2019ve learned how to guide reasoning step-by-step and sample multiple pathways for accuracy. But what happens when a model fails simply because it makes a wrong factual assumption?","sidebar":"guideSidebar"},"core-techniques/meta-prompting":{"id":"core-techniques/meta-prompting","title":"Meta Prompting","description":"You\u2019ve learned how to write clear instructions, teach with examples, and guide step-by-step reasoning.","sidebar":"guideSidebar"},"core-techniques/multimodalcot":{"id":"core-techniques/multimodalcot","title":"Multimodal Chain-of-Thought Prompting","description":"You\u2019ve learned how to guide models using text-based Chain-of-Thought (CoT) reasoning, ReAct loops, and verbal reflection.","sidebar":"guideSidebar"},"core-techniques/pal":{"id":"core-techniques/pal","title":"Program-Aided Language Models (PAL)","description":"You\u2019ve learned how to guide models using step-by-step reasoning, external tools, and automated pipelines.","sidebar":"guideSidebar"},"core-techniques/prompt-chaining":{"id":"core-techniques/prompt-chaining","title":"Prompt Chaining","description":"You\u2019ve learned several ways to improve a single prompt: clearer instructions, examples, step-by-step reasoning, multiple attempts, and generated knowledge.","sidebar":"guideSidebar"},"core-techniques/rag":{"id":"core-techniques/rag","title":"Retrieval-Augmented Generation (RAG)","description":"Language models are powerful, but their knowledge is limited to what they learned during training. When a question requires up-to-date, specialized, or highly specific information, the model can guess \u2014 and sometimes invent facts.","sidebar":"guideSidebar"},"core-techniques/react":{"id":"core-techniques/react","title":"ReAct Prompting","description":"You\u2019ve learned how to guide models through step-by-step text reasoning, ground them with external facts using RAG, and even let them write code execution scripts using PAL.","sidebar":"guideSidebar"},"core-techniques/reflexion":{"id":"core-techniques/reflexion","title":"Reflexion","description":"You\'ve learned how ReAct allows a language model to interleave reasoning and actions. However, when the model makes a mistake, it usually starts the next attempt from scratch.","sidebar":"guideSidebar"},"core-techniques/self-consistency":{"id":"core-techniques/self-consistency","title":"Self-Consistency","description":"Chain-of-Thought (CoT) prompting encourages language models to show their work step-by-step. But what happens if the model makes a minor arithmetic or logical misstep early on, the entire final answer falls apart.","sidebar":"guideSidebar"},"core-techniques/tot":{"id":"core-techniques/tot","title":"Tree of Thoughts (ToT)","description":"You\u2019ve seen how Chain-of-Thought guides a model step by step, and how Self-Consistency samples multiple paths and votes on the answer.","sidebar":"guideSidebar"},"core-techniques/zero-few-shot":{"id":"core-techniques/zero-few-shot","title":"Zero-Shot & Few-Shot Prompting","description":"You\'ve learned how to write clear, structured prompts \u2014 but sometimes, even clear instructions lead to confusing results.","sidebar":"guideSidebar"},"intro":{"id":"intro","title":"Introduction to Prompt Engineering","description":"You\u2019ve probably chatted with an AI assistant \u2014 maybe asked it to write an email, explain a topic, or fix a bit of","sidebar":"guideSidebar"}}}}')}}]);